-- Postgres variant of 0966_account_disable_requests.sql (issue #915). The composite foreign keys stand in for the
-- cross-tenant triggers. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up
CREATE TABLE account_disable_requests (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  account_id BIGINT NOT NULL,
  requested_by TEXT NOT NULL,
  requested_by_user_id TEXT,
  requested_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, account_id),
  FOREIGN KEY (tenant_id, account_id) REFERENCES accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, requested_by_user_id) REFERENCES platform_users (tenant_id, id)
);
